<script lang="ts">
  import { Dialog } from "bits-ui"; import { jsonStore } from "@slop/svelte"; import Plus from "@lucide/svelte/icons/plus"; import Trash2 from "@lucide/svelte/icons/trash-2"; import X from "@lucide/svelte/icons/x";
  type Entry={id:number;day:string;mood:number;energy:number;note:string};type MoodData={title:string;entries:Entry[];nextID:number};
  const log=jsonStore<MoodData>("state",{title:"How are you, really?",entries:[],nextID:1});let adding=$state(false);let editingID=$state<number|null>(null);let mood=$state(3);let energy=$state(3);let note=$state("");
  const average=$derived(log.current.entries.length?log.current.entries.reduce((sum,item)=>sum+item.mood,0)/log.current.entries.length:0);
  const tones=["#e56b67","#e6a662","#e8d982","#9fc5a3","#81b7cb"];
  function setTitle(value:string):void{log.update(data=>{data.title=value})}
  function beginAdd():void{editingID=null;mood=3;energy=3;note="";adding=true}
  function beginEdit(entry:Entry):void{editingID=entry.id;mood=entry.mood;energy=entry.energy;note=entry.note;adding=true}
  function save():void{const clean=note.trim();if(!clean)return;log.update(data=>{if(editingID===null){data.entries.unshift({id:data.nextID,day:"TODAY",mood,energy,note:clean});data.nextID+=1}else{const entry=data.entries.find(item=>item.id===editingID);if(entry){entry.mood=mood;entry.energy=energy;entry.note=clean}}});note="";editingID=null;adding=false}
  function remove():void{if(editingID===null)return;log.update(data=>{data.entries=data.entries.filter(item=>item.id!==editingID)});editingID=null;adding=false}
  function dayWidth(value:number):number{return 24+value*13}
</script>
<main class="mood" data-slop-selection="none"><header><p>DAILY WEATHER / INSIDE</p><input class="mood-title" aria-label="Journal title" value={log.current.title} oninput={(event)=>setTitle(event.currentTarget.value)}/><div class="average"><strong>{average.toFixed(1)}</strong><span>RECENT<br/>AVERAGE</span></div></header><section class="spectrum" aria-label="Recent mood spectrum">{#each log.current.entries.slice(0,7).reverse() as entry}<i style={`background:${tones[entry.mood-1]};height:${dayWidth(entry.energy)}%`} title={`${entry.day}: ${entry.mood} of 5`}></i>{/each}</section><section class="journal"><div class="journal-head"><div><span>RECENT NOTES</span><strong>{log.current.entries.length} check-ins</strong></div><button onclick={beginAdd}><Plus/>Check in</button></div><ol>{#each log.current.entries.slice(0,4) as entry (entry.id)}<li><button class="entry-edit" onclick={()=>beginEdit(entry)} aria-label="Edit check-in"><span class="orb" style={`--tone:${tones[entry.mood-1]}`}><strong>{entry.mood}</strong><span>/5</span></span><span class="entry-copy"><time>{entry.day}</time><span>{entry.note}</span><small>ENERGY {entry.energy}/5</small></span></button></li>{/each}</ol></section><footer><span>No streaks. No judgement.</span><span>Tap a note to edit</span></footer>
<Dialog.Root bind:open={adding}><Dialog.Portal><Dialog.Overlay class="overlay"/><Dialog.Content class="dialog"><form onsubmit={(event)=>{event.preventDefault();save()}}><p>{editingID===null?"ONE HONEST MINUTE":"EDIT CHECK-IN"}</p><Dialog.Title>What is the weather?</Dialog.Title><label>Mood <span>{mood}/5</span><input type="range" min="1" max="5" bind:value={mood}/></label><label>Energy <span>{energy}/5</span><input type="range" min="1" max="5" bind:value={energy}/></label><label>One sentence<textarea bind:value={note} placeholder="Name what is here."></textarea></label><div>{#if editingID!==null}<button class="remove" type="button" onclick={remove}><Trash2/>Delete</button>{/if}<Dialog.Close type="button">Later</Dialog.Close><button type="submit">{editingID===null?"Save check-in":"Save changes"}</button></div></form><Dialog.Close class="close" aria-label="Close"><X/></Dialog.Close></Dialog.Content></Dialog.Portal></Dialog.Root></main>
